package io.github.julianperge.modular_planters.gametest;

import io.github.julianperge.modular_planters.blockentity.ExportBlockEntity;
import io.github.julianperge.modular_planters.multiblock.MeStatus;
import io.github.julianperge.modular_planters.multiblock.OutputSink;
import io.github.julianperge.modular_planters.registry.MPBlocks;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.neoforged.neoforge.transfer.ResourceHandlerUtil;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.item.ItemStacksResourceHandler;

public final class MeLinkTests {
    private static final BlockPos EXPORT = new BlockPos(1, 1, 1);

    private MeLinkTests() {
    }

    public static void register(Map<String, TestCase> into) {
        into.put("online_link_takes_outputs_first", new TestCase(20, MeLinkTests::onlineLinkTakesOutputsFirst));
        into.put("offline_link_sends_outputs_to_export", new TestCase(20, MeLinkTests::offlineLinkSendsOutputsToExport));
        into.put("removed_link_is_skipped_and_marks_stale",
                new TestCase(20, MeLinkTests::removedLinkIsSkippedAndMarksStale));
        into.put("room_counts_me_room", new TestCase(20, MeLinkTests::roomCountsMeRoom));
        into.put("me_partial_room_sends_the_rest_to_export",
                new TestCase(20, MeLinkTests::mePartialRoomSendsTheRestToExport));
    }

    private static ExportBlockEntity placeExport(GameTestHelper helper) {
        helper.setBlock(EXPORT, MPBlocks.EXPORT.get());
        return helper.getBlockEntity(EXPORT, ExportBlockEntity.class);
    }

    private static int count(ExportBlockEntity export, Item item) {
        ItemStacksResourceHandler storage = export.storage();
        int total = 0;
        for (int slot = 0; slot < storage.size(); slot++) {
            total += storage.getResource(slot).getItem() == item ? storage.getAmountAsInt(slot) : 0;
        }
        return total;
    }

    private static void onlineLinkTakesOutputsFirst(GameTestHelper helper) {
        ExportBlockEntity export = placeExport(helper);
        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 1000);
        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
        helper.assertTrue(sink.insert(new ItemStack(Items.WHEAT, 64)).isEmpty(), "nothing left over");
        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 64L, "wheat in ME");
        helper.assertValueEqual(count(export, Items.WHEAT), 0, "wheat in export");
        helper.succeed();
    }

    private static void offlineLinkSendsOutputsToExport(GameTestHelper helper) {
        ExportBlockEntity export = placeExport(helper);
        FakeMeLink me = new FakeMeLink(MeStatus.OFFLINE, 1000);
        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
        helper.assertTrue(sink.insert(new ItemStack(Items.WHEAT, 64)).isEmpty(), "nothing left over");
        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 0L, "wheat in ME");
        helper.assertValueEqual(count(export, Items.WHEAT), 64, "wheat in export");
        helper.succeed();
    }

    private static void removedLinkIsSkippedAndMarksStale(GameTestHelper helper) {
        ExportBlockEntity export = placeExport(helper);
        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 1000);
        me.removed = true;
        AtomicBoolean stale = new AtomicBoolean();
        OutputSink sink = new OutputSink(List.of(export), me, () -> stale.set(true));
        helper.assertTrue(sink.insert(new ItemStack(Items.WHEAT, 64)).isEmpty(), "nothing left over");
        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 0L, "wheat in ME");
        helper.assertValueEqual(count(export, Items.WHEAT), 64, "wheat in export");
        helper.assertTrue(stale.get(), "onStale ran");
        helper.succeed();
    }

    private static void roomCountsMeRoom(GameTestHelper helper) {
        ExportBlockEntity export = placeExport(helper);
        int full = ExportBlockEntity.SLOTS * 64;
        helper.assertValueEqual(
                ResourceHandlerUtil.insertStacking(export.storage(), ItemResource.of(Items.COBBLESTONE), full, null), full,
                "pre-filled cobblestone");
        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 64);
        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
        helper.assertTrue(sink.hasRoomFor(List.of(new ItemStack(Items.WHEAT, 64))), "ME room counts");
        helper.assertTrue(!sink.hasRoomFor(List.of(new ItemStack(Items.WHEAT, 65))), "65 do not fit");
        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 0L, "the simulation stored nothing");
        helper.succeed();
    }

    private static void mePartialRoomSendsTheRestToExport(GameTestHelper helper) {
        ExportBlockEntity export = placeExport(helper);
        FakeMeLink me = new FakeMeLink(MeStatus.ONLINE, 10);
        OutputSink sink = new OutputSink(List.of(export), me, () -> {});
        List<ItemStack> drops = List.of(new ItemStack(Items.WHEAT, 64), new ItemStack(Items.WHEAT, 64));
        helper.assertTrue(sink.hasRoomFor(drops), "room");
        for (ItemStack drop : drops) {
            helper.assertTrue(sink.insert(drop.copy()).isEmpty(), "nothing left over");
        }
        helper.assertValueEqual(me.stored(ItemResource.of(Items.WHEAT)), 10L, "wheat in ME");
        helper.assertValueEqual(count(export, Items.WHEAT), 118, "wheat in export");
        helper.succeed();
    }
}
package io.github.julianperge.modular_planters.gametest;

import io.github.julianperge.modular_planters.multiblock.MeLink;
import io.github.julianperge.modular_planters.multiblock.MeStatus;
import java.util.HashMap;
import java.util.Map;
import net.neoforged.neoforge.transfer.item.ItemResource;

public final class FakeMeLink implements MeLink {
    public MeStatus status;
    public boolean removed;
    public ItemResource filter = ItemResource.EMPTY;
    public long energy;
    public long modulateShortfall;

    private final long capacity;
    private final Map<ItemResource, Long> items = new HashMap<>();

    public FakeMeLink(MeStatus status, long capacity) {
        this.status = status;
        this.capacity = capacity;
    }

    public long stored(ItemResource resource) {
        return items.getOrDefault(resource, 0L);
    }

    public void put(ItemResource resource, long amount) {
        items.merge(resource, amount, Long::sum);
    }

    @Override
    public MeStatus status() {
        return status;
    }

    @Override
    public long insertItem(ItemResource resource, long amount, boolean simulate) {
        if (status != MeStatus.ONLINE) {
            return 0;
        }
        long total = items.values().stream().mapToLong(Long::longValue).sum();
        long accepted = Math.min(amount, Math.max(0, capacity - total));
        if (simulate) {
            return accepted;
        }
        long inserted = Math.max(0, accepted - modulateShortfall);
        put(resource, inserted);
        return inserted;
    }

    @Override
    public long extractItem(ItemResource resource, long amount, boolean simulate) {
        if (status != MeStatus.ONLINE) {
            return 0;
        }
        long extracted = Math.min(amount, stored(resource));
        if (!simulate) {
            items.merge(resource, -extracted, Long::sum);
        }
        return extracted;
    }

    @Override
    public long extractEnergy(long amount, boolean simulate) {
        if (status != MeStatus.ONLINE) {
            return 0;
        }
        long extracted = Math.min(amount, energy);
        if (!simulate) {
            energy -= extracted;
        }
        return extracted;
    }

    @Override
    public ItemResource fertilizerFilter() {
        return filter;
    }

    @Override
    public boolean isRemoved() {
        return removed;
    }
}
package io.github.julianperge.modular_planters.logic;

import io.github.julianperge.modular_planters.logic.PlanterTicker.AdvanceResult;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PlanterTickerTest {
    static final AteNumbers D = AteDefaults.NUMBERS;
    static final ModuleSet TWO_MK3 = new ModuleSet(ModuleKind.SPEED_MK3, ModuleKind.SPEED_MK3);

    static SeedBin<String> bin(int n) {
        SeedBin<String> b = new SeedBin<>(String::equals, s -> s);
        b.add("a", n);
        return b;
    }

    @Test
    void pausesTheWholePlanterWhenEnergyIsShort() {
        SeedBin<String> b = bin(4);
        List<Group> g = Grouping.of(b, Collections.nCopies(4, TWO_MK3));
        AdvanceResult r = PlanterTicker.advance(b, g, x -> 75, m -> 512, 2047);
        assertTrue(r.pausedForPower());
        assertEquals(0, r.energyUsed());
        for (int i = 0; i < 4; i++) {
            assertEquals(0, b.progress(i));
        }
    }

    @Test
    void growthTimeIsAskedOncePerGroupAndNotWhilePaused() {
        SeedBin<String> b = bin(3);
        b.add("b", 1);
        List<Group> g = Grouping.of(b, Collections.nCopies(4, ModuleSet.EMPTY));
        AtomicInteger asked = new AtomicInteger();
        PlanterTicker.advance(b, g, x -> {
            asked.incrementAndGet();
            return 10;
        }, m -> 1, 4);
        assertEquals(2, asked.get());
        PlanterTicker.advance(b, Grouping.of(b, Collections.nCopies(4, ModuleSet.EMPTY)), x -> {
            asked.incrementAndGet();
            return 10;
        }, m -> 1, 3);
        assertEquals(2, asked.get());
    }

    @Test
    void readySeedsDrawNoPower() {
        SeedBin<String> b = bin(2);
        b.markReady(0);
        AtomicInteger asked = new AtomicInteger();
        AdvanceResult r = PlanterTicker.advance(b, Grouping.of(b, Collections.nCopies(2, TWO_MK3)), x -> {
            asked.incrementAndGet();
            return 75;
        }, m -> 512, 512);
        assertEquals(512, r.energyUsed());
        assertEquals(1, b.progress(1));
        assertEquals(0, b.progress(0));
        assertTrue(b.ready(0));
        assertEquals(1, asked.get());
    }

    @Test
    void seedsBecomeReadyWhenProgressReachesGrowthTime() {
        SeedBin<String> b = bin(1);
        for (int t = 0; t < 3; t++) {
            PlanterTicker.advance(b, Grouping.of(b, List.of(ModuleSet.EMPTY)), x -> 3, m -> 1, 1);
        }
        assertTrue(b.ready(0));
    }

    @Test
    void aFullPlanterBlockMatches64PoweredPlanters() {
        int harvests = assertMatchesPoweredPlanters(64, 64, ModuleKind.SPEED_MK3, 64, ModuleKind.SPEED_MK3, 64, 1.75f, 1200);
        assertEquals(1024, harvests);
    }

    @Test
    void aPartlyUpgradedShortOnSoilBlockMatchesItsPoweredPlanters() {
        assertMatchesPoweredPlanters(64, 13, ModuleKind.SPEED_MK3, 23, ModuleKind.YIELD_MK1, 10, 1.75f, 2400);
    }

    // Runs one planter block and one Powered Planter per growing seed side by side, asserts that
    // their harvests and energy agree, and returns the harvest count.
    private static int assertMatchesPoweredPlanters(int seeds, int soil, ModuleKind m1, int m1Count,
                                                    ModuleKind m2, int m2Count, float soilModifier, int ticks) {
        int growing = Coverage.growing(seeds, soil);
        List<ModuleSet> coverage = Coverage.assign(growing, m1, m1Count, m2, m2Count);
        SeedBin<String> block = bin(seeds);
        List<ReferencePoweredPlanter> planters = new ArrayList<>();
        for (int i = 0; i < growing; i++) {
            planters.add(new ReferencePoweredPlanter());
        }

        long blockEnergy = 0;
        int blockHarvests = 0;
        for (int t = 0; t < ticks; t++) {
            AdvanceResult r = PlanterTicker.advance(block, Grouping.of(block, coverage),
                    g -> GrowthMath.growthTime(D, soilModifier, g.modules(), 1f),
                    m -> GrowthMath.powerPerSeedTick(D, m), Long.MAX_VALUE);
            blockEnergy += r.energyUsed();
            for (int i = 0; i < growing; i++) {
                if (block.ready(i)) {
                    blockHarvests++;
                    block.reset(i);
                }
            }
            for (int i = 0; i < growing; i++) {
                ModuleSet modules = coverage.get(i);
                planters.get(i).tick(GrowthMath.growthTime(D, soilModifier, modules, 1f), GrowthMath.powerPerSeedTick(D, modules));
            }
        }

        int referenceHarvests = planters.stream().mapToInt(p -> p.harvests).sum();
        long referenceEnergy = planters.stream().mapToLong(p -> p.energyUsed).sum();
        assertEquals(referenceHarvests, blockHarvests);
        assertEquals(referenceEnergy, blockEnergy);
        return blockHarvests;
    }
}
